(()=>{
'use strict';
// 全部内容为本地演示，不调用真实 AI、报名、付款、通知或第三方服务。
const KEY='aisports-ai-native-consumer-v1';
const main=document.getElementById('main'),modal=document.getElementById('modal'),assistant=document.getElementById('assistant'),messages=document.getElementById('assistant-messages');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const button=(text,action,cls='',attrs='')=>`<button class="button ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const events=[
 {id:'autumn',name:'保定秋季羽毛球公开赛',date:'2026-11-07',dateText:'11月7—8日',place:'市体育中心（演示场地）',city:'保定',cover:'event-court.svg',caption:'AUTUMN OPEN',status:'报名中',deadline:'2026-11-02 20:00',organizer:'城市运动协会（演示）',review:true,fee:true,level:'有赛事经验者',reason:'与你关注的城市和项目一致',rules:['报名窗口截至 2026 年 11 月 2 日 20:00，比赛为 11 月 7—8 日。','成人男单 A 组：18—34 岁；成人混双 A 组：两名成员均须符合该年龄范围。出生日期与资格由正式报名资料核验，自评水平不作为资格结论。','报名费用：男单 200 元／单，混双 400 元／整单。正式提交后才能办理付款，收费实际足额收款后才可审核通过。','双打成员须本人填写并确认资料；草稿不占名额、不预付款。正式提交时才检查资格、名额及规则。','若拒绝或合法撤回，按本场公开的退改说明人工办理；本原型不办理实际付款或退款。'],projects:[{id:'single',name:'成人男单 A 组',members:1,amount:200,note:'18—34 岁 · 单人项目'},{id:'mixed',name:'成人混双 A 组',members:2,amount:400,note:'18—34 岁 · 双人项目'}]},
 {id:'weekend',name:'周末羽毛球交流赛',date:'2026-10-24',dateText:'10月24日',place:'城北运动馆（演示场地）',city:'保定',cover:'event-community.svg',caption:'WEEKEND TOGETHER',status:'报名中',deadline:'2026-10-21 18:00',organizer:'同城羽毛球俱乐部（演示）',review:true,fee:false,level:'入门与日常爱好者',reason:'同城 · 报名开放 · 交流活动',rules:['报名窗口截至 2026 年 10 月 21 日 18:00，比赛为 10 月 24 日。','成人交流活动，年龄 18 岁及以上；以主办方正式发布的资格要求为准。入门与日常爱好者为活动建议，自评不等于官方段位。','本场示例为免费赛事，无付款步骤；正式提交后由承办方核对资格，不代表自动通过。','单人练习赛需要一名成员，混双交流赛需要两名成员。双打伙伴需使用本人账号填写并确认，成员未齐不可正式提交。','草稿不占名额；报名成功后关注站内消息，比赛当天按安排报到。'],projects:[{id:'practice',name:'成人单人练习赛',members:1,amount:0,note:'18 岁以上 · 单人项目'},{id:'social',name:'成人混双交流赛',members:2,amount:0,note:'18 岁以上 · 双人项目'}]}
];
const defaults={city:'保定',sport:'羽毛球',level:'入门',bookmarks:[],drafts:[]};
let state={...defaults};
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&typeof saved==='object'){state.city=['保定','全部'].includes(saved.city)?saved.city:'保定';state.sport='羽毛球';state.level=['入门','日常爱好者','有赛事经验'].includes(saved.level)?saved.level:'入门';state.bookmarks=Array.isArray(saved.bookmarks)?saved.bookmarks.filter(id=>events.some(e=>e.id===id)):[];state.drafts=Array.isArray(saved.drafts)?saved.drafts.filter(d=>d&&typeof d.id==='string'&&events.some(e=>e.id===d.event&&e.projects.some(p=>p.id===d.project))).slice(0,20):[]}}catch{}
let eventQuery='',filter='recommended',statusFilter='all',savedOnly=false,toastTimer,lastFocus,position=null,chatStarted=false;
const findEvent=id=>events.find(e=>e.id===id);
const route=()=>{const parts=location.hash.slice(1).split('/');return{page:parts[0]||'discover',event:parts[0]==='event'?findEvent(parts[1]):null}};
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{notify('浏览器无法保存，数据仅保留在当前页面。');return false}}
function notify(text){const t=document.getElementById('toast');t.textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.textContent='',3500)}
function openModal(title,html){document.getElementById('modal-title').textContent=title;document.getElementById('modal-body').innerHTML=html;if(!modal.open)modal.showModal()}
function closeModal(){modal.close()}
function setRoute(value){location.hash=value}
function eventCard(e){return`<article class="event-card"><a href="#event/${e.id}" class="event-cover" aria-label="查看${esc(e.name)}"><img src="assets/${e.cover}" alt="羽毛球场地平面插画" loading="lazy"><span class="status-pill">${e.status}</span><span class="cover-caption">${e.caption}</span></a><div class="event-body"><h3><a href="#event/${e.id}">${e.name}</a></h3><div class="event-meta">${icon('calendar')}<span>${e.dateText} · ${e.place.replace('（演示场地）','')}</span></div><div class="event-meta">${icon('file')}<span>${e.fee?'项目与费用以示例规程为准':'免费交流 · 需核对参赛资格'}</span></div><div class="event-bottom"><span class="reason">${icon('spark')}${filter==='level'?e.level:e.id==='weekend'?'同城 · 交流活动':'保定 · 羽毛球 · 报名开放'}</span><a class="button primary" href="#event/${e.id}">查看赛事 ${icon('chevron')}</a></div></div></article>`}
function taskCard(){return`<article class="task-card"><span class="status-pill">待伙伴确认</span><h3>周末混双交流赛</h3><div class="event-meta">${icon('calendar')}<span>10月24日 · 城北运动馆</span></div><div class="task-members"><span class="avatar" aria-label="本人已确认">林</span><span class="plus">+</span><span class="avatar empty" aria-label="一名伙伴待确认">${icon('user')}</span><span class="member-count">成员确认 1/2</span>${button('邀请伙伴','invite','coral')}</div><div class="steps" aria-label="当前阶段：确认成员"><div class="step current"><span>1</span>确认成员</div><div class="step"><span>2</span>提交报名</div><div class="step"><span>3</span>参赛</div></div></article>`}
function supportCard(){return`<div class="support-card"><span class="support-icon">${icon('file')}</span><div><strong>参赛有疑问？</strong><p>问 AI 看懂规程与报名状态</p></div><button class="button outline" data-ai="我的参赛下一步是什么？">询问 AI ${icon('chevron')}</button></div>`}
function filterRow(){return`<div class="filter-row"><button class="chip ${filter==='recommended'?'active':''}" data-filter="recommended" aria-pressed="${filter==='recommended'}">推荐</button><button class="chip ${filter==='city'?'active':''}" data-filter="city" aria-pressed="${filter==='city'}">${state.city==='全部'?'全部城市':'保定'}</button><button class="chip ${filter==='level'?'active':''}" data-filter="level" aria-pressed="${filter==='level'}">适合我的水平</button><button class="chip ${filter==='open'?'active':''}" data-filter="open" aria-pressed="${filter==='open'}">报名中</button><button class="filter-button" data-action="filters">${icon('filter')}手动筛选</button></div>`}
function filteredEvents(){let found=events.filter(e=>e.name.includes(eventQuery.trim()));if(filter==='level')found=found.filter(e=>state.level==='入门'?e.id==='weekend':true);if(statusFilter==='ended')found=[];if(savedOnly)found=found.filter(e=>state.bookmarks.includes(e.id));return found}
function emptyEvents(){return`<div class="empty-state"><strong>暂时没有符合条件的赛事</strong><p>试试调整关键词或筛选条件。</p>${button('重置筛选','clear-filters','outline')}</div>`}
function renderDiscover(){return`<section class="hero"><div class="hero-art" role="img" aria-label="跑步、骑行、篮球与伸展运动的社区生活插画"></div><div class="hero-inner"><p class="eyebrow">你的 AI 参赛伙伴</p><h1>下一场，<br>开启你的<em>精彩</em></h1><p class="hero-subtitle">找比赛、看懂规程，把参赛准备交给 AI</p><button class="preference-pill" data-action="preference">${icon('racket')}羽毛球 · 自评${esc(state.level)} ${icon('chevron')}</button><div class="hero-command"><div class="command-heading">${icon('spark')}AI 参赛助手</div><form class="hero-prompt" id="hero-form"><input name="prompt" aria-label="向AI描述参赛需求" maxlength="500" placeholder="这个周末，保定有哪些适合我的比赛？"><button type="submit" class="ai-send" aria-label="开始AI参赛对话">${icon('arrow')}</button></form><div class="hero-shortcuts"><button data-ai="有哪些适合我的比赛？">${icon('search')}AI 找赛事</button><button data-ai="帮我看懂赛事规程">${icon('file')}看懂规程</button><button data-ai="我的参赛下一步是什么？">${icon('user')}我的参赛</button></div></div></div></section><div class="content-grid"><section><div class="section-heading"><div class="section-title"><h2>为你发现</h2><span class="small-label">示例推荐</span></div><a href="#events" class="text-link">更多赛事 ${icon('chevron')}</a></div>${filterRow()}<div class="event-grid">${filteredEvents().map(eventCard).join('')||emptyEvents()}</div><p class="recommendation-note">推荐依据：${state.city==='全部'?'全部城市':'保定'}、羽毛球兴趣与报名开放状态；选择「适合我的水平」会优先展示入门交流活动。自评不等于资格或官方段位。</p></section><aside class="task-column"><div class="section-heading"><h2>我的下一步</h2><a class="text-link" href="#participation">全部 ${icon('chevron')}</a></div>${taskCard()}${supportCard()}<div class="quiet-card"><span class="caption">YOUR NEXT CHAPTER</span><h3>不只是一场比赛</h3><p>从第一次报名，到下一次一起上场。<br>你的运动故事，从参与开始。</p><a href="#profile" class="text-link">完善我的运动偏好 ${icon('chevron')}</a></div></aside></div>`}
function renderEvents(){const found=filteredEvents();return`<div class="page-container"><div class="page-heading"><h1>找到你的下一场</h1><p>每一次上场，都值得期待。当前示例赛事为羽毛球，更多运动项目将在有真实内容后展示。</p></div><form class="search-bar" id="event-search">${icon('search')}<input name="query" value="${esc(eventQuery)}" placeholder="搜索赛事名称" aria-label="搜索赛事名称"><button class="button primary" type="submit">搜索</button></form>${filterRow()}<p class="section-subtext">${savedOnly?'只看已收藏 · ':''}找到 ${found.length} 场示例赛事${filter==='level'?' · 根据自评水平筛选':''}</p><div class="event-grid listing-grid">${found.map(eventCard).join('')||emptyEvents()}</div></div>`}
function renderDetail(e){const saved=state.bookmarks.includes(e.id);return`<div class="page-container"><nav class="breadcrumb" aria-label="面包屑"><a href="#discover">发现</a>${icon('chevron')}<a href="#events">赛事</a>${icon('chevron')}<span>${e.name}</span></nav><section class="detail-intro"><img src="assets/${e.cover}" alt="羽毛球赛事场地插画"><div class="detail-info"><span class="status-pill">报名中 · 示例赛事</span><h1>${e.name}</h1><div class="event-meta">${icon('calendar')}<span>${e.dateText} · 截止报名 ${e.deadline}</span></div><div class="event-meta">${icon('pin')}<span>${e.place}</span></div><div class="event-meta">${icon('file')}<span>${e.organizer} · ${e.fee?'收费赛事':'免费赛事'} · 需审核</span></div><div class="detail-actions">${button('开始报名草稿','signup','primary',`data-event="${e.id}"`)}<button class="button outline" data-ai="帮我看懂当前赛事规程">${icon('spark')}AI 解读规程</button><button class="button outline bookmark-button" data-action="bookmark" data-event="${e.id}" aria-pressed="${saved}">${icon('heart')}${saved?'已收藏':'收藏'}</button></div></div></section><div class="detail-layout"><div><section class="panel" id="projects"><h2>选择你的参赛项目</h2><div class="project-list">${e.projects.map(p=>`<div class="project-item"><span>${icon('racket')}</span><div><strong>${p.name}</strong><p>${p.note} · 成员本人确认</p></div><div class="price">${p.amount?'¥ '+p.amount:'免费'}<span style="font-size:10px;font-weight:400">${p.amount?' / 单':''}</span></div></div>`).join('')}</div><p class="form-help">金额为整单口径，来自本场示例规程。草稿不占名额、不预付款；本原型不会向正式报名系统提交。</p></section><section class="panel" id="rules"><h2>参赛前，先了解这些</h2><span class="source-label">来源：本场演示规程 · R1—R5</span><ol class="rule-list">${e.rules.map(r=>`<li>${r}</li>`).join('')}</ol></section></div><aside><section class="panel"><div class="command-heading">${icon('spark')}让 AI 帮你看懂</div><p>年龄、组别、费用、成员确认，按你关心的问题查看规程依据。</p><button class="button outline" data-ai="这场比赛的费用和报名条件是什么？">问这场赛事 ${icon('arrow')}</button></section><section class="panel"><h2>赛事安排</h2><p>${icon('calendar')} ${e.dateText}</p><p>${icon('pin')} ${e.place}</p><p>报到与场次安排，以主办方正式通知为准。本页没有实时导航、住宿或交通报价。</p>${button('查看示例通知','messages','outline')}</section></aside></div></div>`}
function renderParticipation(){return`<div class="page-container"><div class="page-heading"><h1>我的参赛</h1><p>从确认伙伴，到正式报名，再到上场。先把眼前的下一步做好。</p></div><div class="participation-grid">${taskCard()}${state.drafts.map(d=>{const e=findEvent(d.event),p=e.projects.find(x=>x.id===d.project);return`<article class="draft-card"><span class="status-pill">本地草稿 · 未正式提交</span><h3>${e.name}</h3><p>${p.name} · 成员确认 1/${p.members}<br>${e.dateText} · ${p.amount?'整单应付示例 ¥'+p.amount:'免费赛事'}<br>${p.members===2?'需要伙伴本人填写并确认，草稿不占名额。':'正式提交前仍需填写本人档案并校验资格。'}</p><a href="#event/${e.id}" class="button outline">查看赛事 ${icon('chevron')}</a> ${button('删除草稿','delete-draft','',`data-draft="${esc(d.id)}"`)}</article>`}).join('')}<article class="draft-card"><div class="command-heading">${icon('spark')}让准备更轻松</div><h3>还有什么需要确认？</h3><p>让 AI 按当前赛事的规程，说明项目、费用与报名步骤。</p><button class="button outline" data-ai="我的参赛下一步是什么？">问我的下一步 ${icon('arrow')}</button></article></div><p class="recommendation-note">以上为示例个人状态与当前浏览器中的草稿；没有真实参赛记录、付款或资格审核结果。</p></div>`}
function renderProfile(){return`<div class="page-container"><div class="profile-layout"><section class="profile-summary"><span class="avatar">林</span><h1>你好，林同学</h1><p>不急着定义自己，先享受每一次参与。</p><button class="preference-pill" data-action="preference">${icon('racket')}羽毛球 · 自评${esc(state.level)} ${icon('chevron')}</button><div class="profile-metrics"><a href="#participation"><strong>${1+state.drafts.length}</strong><span>待办与草稿</span></a><button class="reset-link" data-action="saved" style="margin:0;text-align:left"><strong>${state.bookmarks.length}</strong><span>收藏赛事</span></button></div><p class="form-help" style="margin-top:20px">自评用于偏好筛选，不是官方竞技评级。</p></section><section class="panel"><h2>我的运动偏好</h2><form id="preference-form" class="form-stack">${preferenceFields()}<div class="form-actions"><button type="submit" class="button primary">保存偏好</button></div></form><button class="reset-link" data-action="reset">重置本原型的本地数据</button></section></div></div>`}
function preferenceFields(){return`<label class="form-field">关注城市<select name="city"><option ${state.city==='保定'?'selected':''}>保定</option><option ${state.city==='全部'?'selected':''}>全部</option></select></label><label class="form-field">关注项目<select name="sport"><option>羽毛球</option></select></label><label class="form-field">我的自评水平<select name="level">${['入门','日常爱好者','有赛事经验'].map(l=>`<option ${state.level===l?'selected':''}>${l}</option>`).join('')}</select></label><p class="form-help">这里只展示当前有赛事内容的项目。偏好仅保存在当前浏览器，不会生成竞技段位或公开运动画像。</p>`}
function render(){const r=route();let active=r.page==='event'?'events':r.page;main.innerHTML=r.page==='discover'?renderDiscover():r.page==='events'?renderEvents():r.page==='participation'?renderParticipation():r.page==='profile'?renderProfile():r.event?renderDetail(r.event):`<div class="page-container"><div class="empty-state"><strong>没有找到这个页面</strong><p>请从赛事列表重新选择。</p><a class="button primary" href="#events">返回赛事</a></div></div>`;document.querySelectorAll('[data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===active);if(a.dataset.route===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.getElementById('city-label').textContent=state.city;document.title=`AI运动 · ${r.event?r.event.name:{discover:'发现你的下一场',events:'赛事发现',participation:'我的参赛',profile:'我的运动偏好'}[r.page]||'页面未找到'}`;updateContext()}
function updateContext(){const r=route();document.getElementById('assistant-context').textContent=`正在讨论：${r.event?r.event.name:{discover:'发现首页',events:'赛事列表',participation:'我的参赛',profile:'我的运动偏好'}[r.page]||'未知页面'} · 当前路由 ${location.hash||'#discover'}`}
function appendMessage(html,user=false){const node=document.createElement('div');node.className=`assistant-message${user?' user':''}`;node.innerHTML=html;messages.append(node);messages.scrollTop=messages.scrollHeight;return node}
function openAssistant(){if(assistant.hidden){lastFocus=document.activeElement;assistant.hidden=false;document.getElementById('ai-launcher').setAttribute('aria-expanded','true');updateContext();if(!chatStarted){appendMessage(`<strong>你好，我是你的 AI 参赛助手。</strong><p>说说你想找什么比赛，或让我帮你看懂规程、整理报名下一步。</p><span class="source-label">这里使用本地示例回复，未接入真实模型</span>`);chatStarted=true}document.getElementById('assistant-input').focus()}}
function closeAssistant(){assistant.hidden=true;document.getElementById('ai-launcher').setAttribute('aria-expanded','false');if(lastFocus?.isConnected)lastFocus.focus()}
function aiEvent(e){return`<div class="assistant-event"><strong>${e.name}</strong><small>${e.dateText} · ${e.place.replace('（演示场地）','')}</small><small>推荐依据：${e.reason}</small><a class="button outline" href="#event/${e.id}" data-chat-navigate>查看赛事 ${icon('chevron')}</a> ${button('建立草稿','signup','',`data-event="${e.id}"`)}</div>`}
function reply(input){const text=String(input).trim().slice(0,500);if(!text)return;openAssistant();appendMessage(esc(text),true);const r=route();if(/下一步|我的参赛|报名状态/.test(text)){appendMessage(`<strong>你的下一步是邀请并等待伙伴本人确认。</strong><p>周末混双交流赛目前成员确认 1/2，仍是草稿，不占名额。等伙伴本人补齐资料并确认后，才可按正式流程提交。</p>${state.drafts.length?`<p>本浏览器另有 ${state.drafts.length} 份本地草稿，均未正式提交。</p>`:''}<span class="source-label">依据：当前个人示例待办、周末交流赛 R4—R5</span><div>${button('查看邀请说明','invite','outline')} <a class="button outline" href="#participation" data-chat-navigate>打开我的参赛</a></div>`);return}
 if(/规程|规则|条件|费用|年龄|资格|组别|付款/.test(text)){if(!r.event){appendMessage(`<strong>先选择你想了解的赛事。</strong><p>每场的年龄、项目、费用和报名规则不同。我会基于所选赛事给出解释和对应原文。</p>${events.map(aiEvent).join('')}`);return}const e=r.event;appendMessage(`<strong>${e.name} · 参赛要点</strong><ul><li>${e.projects.map(p=>`${p.name}（${p.members} 人，${p.amount?'¥'+p.amount+'/整单':'免费'}）`).join('；')}</li><li>报名截止 ${e.deadline}。自评水平用于推荐，资格须核对正式资料。</li><li>${e.fee?'正式提交后才可付款；实际足额收款后才可通过审核。':'本场为免费示例，无付款步骤；正式提交后仍须审核资格。'}</li></ul><span class="source-label">依据：本场演示规程 R1—R4</span><div class="rule-quote">${e.rules[2]}</div>${button('查看规程原文','show-rules','outline',`data-event="${e.id}"`)}`);return}
 if(/比赛|赛事|周末|推荐|找|羽毛球/.test(text)){if(/周末|本周/.test(text)){appendMessage(`<p>示例快照时间为 2026 年 10 月 8 日，本周末没有已配置的示例赛事。下面是之后开放报名的赛事，不能视为实时赛历。</p>${events.filter(e=>state.level==='入门'?e.id==='weekend':true).map(aiEvent).join('')}`)}else appendMessage(`<strong>按你的城市、羽毛球兴趣和自评水平，先看看这些。</strong><p>入门优先交流活动；自评不作为资格判断。当前仅使用本地示例赛事，无法查询实时名额。</p>${events.filter(e=>state.level==='入门'?e.id==='weekend':true).map(aiEvent).join('')}`);return}
 appendMessage('<p>这份原型可以演示找赛事、解读示例规程和查看个人下一步。你可以点下方常用指令体验；其他问题暂未接入真实 AI。</p>')}
function signup(eventId){const e=findEvent(eventId);if(!e)return;openModal('建立参赛草稿',`<div class="callout">${e.name}<br>只保存当前浏览器中的示例草稿，不会正式报名、占名额或收款。</div><form id="signup-form" class="form-stack" data-event="${e.id}"><label class="form-field">参赛项目<select name="project">${e.projects.map(p=>`<option value="${p.id}">${p.name} · ${p.amount?'¥'+p.amount+'/整单':'免费'}</option>`).join('')}</select></label><div id="signup-description" class="form-help">${e.projects[0].members===1?'单人项目，正式提交前须填写本人档案并核验资格。':'双人项目，需要伙伴本人填写并确认。'}</div><label class="check-field"><input type="checkbox" name="read" required><span>我已阅读本场示例规程，并理解此处仅创建草稿，不表示报名成功。</span></label><div id="signup-error" class="error-text" role="alert"></div><div class="form-actions">${button('查看规程','show-rules','outline',`data-event="${e.id}"`)}<button class="button primary" type="submit">保存草稿（演示）</button></div></form>`)}
function showRules(id){const e=findEvent(id);if(!e)return;openModal('示例规程原文',`<p class="section-subtext">${e.name} · 仅作交互演示</p><ol class="rule-list">${e.rules.map((text,i)=>`<li><strong>R${i+1}</strong> ${text}</li>`).join('')}</ol>${button('返回建立草稿','signup','outline',`data-event="${e.id}"`)}`)}
function showInvite(){openModal('邀请你的双打伙伴',`<div class="callout warm">成员确认 1/2 · 当前仍是报名草稿<br>伙伴须使用本人账号补齐并确认资料，你不能代替对方确认。</div><p class="form-help">下面是邀请说明示例，可以复制给伙伴参考；没有创建真实邀请链接，也不会发送消息。</p><div class="copy-box" id="invite-text">想邀请你一起参加周末羽毛球混双交流赛。示例比赛时间：10 月 24 日，地点：城北运动馆。正式使用时，请从平台有效邀请入口，用本人账号填写并确认资料。</div><div class="form-actions">${button('查看赛事','invite-event','outline')}${button('复制说明','copy-invite','primary')}</div>`)}
async function copyInvite(){const content=document.getElementById('invite-text');if(!content)return;try{await navigator.clipboard.writeText(content.textContent);notify('邀请说明已复制，未发送给任何人。')}catch{const selection=window.getSelection();const range=document.createRange();range.selectNodeContents(content);selection.removeAllRanges();selection.addRange(range);notify('已选中说明，请手动复制。')}}
function showFilters(){openModal('按你的节奏找比赛',`<form class="form-stack" id="filter-form"><label class="form-field">城市<select name="city"><option ${state.city==='保定'?'selected':''}>保定</option><option ${state.city==='全部'?'selected':''}>全部</option></select></label><label class="form-field">比赛状态<select name="status"><option value="all" ${statusFilter==='all'?'selected':''}>全部</option><option value="open" ${statusFilter==='open'?'selected':''}>报名中</option><option value="ended" ${statusFilter==='ended'?'selected':''}>已结束</option></select></label><label class="check-field"><input type="checkbox" name="saved" ${savedOnly?'checked':''}><span>只看已收藏</span></label><p class="form-help">当前仅有保定羽毛球示例赛事。没有真实内容的项目和城市暂不作为虚构选项。</p><div class="form-actions">${button('重置','clear-filters','outline')}<button type="submit" class="button primary">应用筛选</button></div></form>`)}
function handleAction(action,target){switch(action){
 case 'open-assistant':openAssistant();break;
 case 'close-modal':closeModal();break;
 case 'city':openModal('选择关注城市',`<div class="callout">当前示例内容来自保定，切换为全部可查看所有已配置示例。</div><div class="form-actions">${button('保定','set-city','outline','data-city="保定"')}${button('全部','set-city','outline','data-city="全部"')}</div>`);break;
 case 'set-city':state.city=target.dataset.city;persist();closeModal();render();break;
 case 'preference':openModal('我的运动偏好',`<form id="preference-form" class="form-stack">${preferenceFields()}<div class="form-actions"><button class="button primary" type="submit">保存偏好</button></div></form>`);break;
 case 'filters':showFilters();break;
 case 'clear-filters':eventQuery='';filter='recommended';statusFilter='all';savedOnly=false;closeModal();render();break;
 case 'signup':signup(target.dataset.event);break;
 case 'show-rules':showRules(target.dataset.event);break;
 case 'invite':showInvite();break;
 case 'invite-event':closeModal();setRoute('event/weekend');break;
 case 'copy-invite':copyInvite();break;
 case 'bookmark':{const e=findEvent(target.dataset.event);if(!e)return;state.bookmarks=state.bookmarks.includes(e.id)?state.bookmarks.filter(id=>id!==e.id):[...state.bookmarks,e.id];persist();const y=scrollY;render();scrollTo(0,y);notify(state.bookmarks.includes(e.id)?'已收藏到当前浏览器。':'已取消收藏。');break}
 case 'saved':savedOnly=true;setRoute('events');break;
 case 'delete-draft':state.drafts=state.drafts.filter(d=>d.id!==target.dataset.draft);persist();render();notify('本地草稿已删除。');break;
 case 'messages':openModal('我的消息',`<span class="source-label">固定示例 · 没有真实通知发送</span><ul class="message-list"><li><strong>请邀请你的双打伙伴</strong>周末混双交流赛还差一名成员本人确认。<small>参赛任务示例</small></li><li><strong>赛前留意赛事安排</strong>报到时间与场次，以主办方正式通知为准。<small>提示示例</small></li></ul>`);break;
 case 'reset':openModal('重置本地示例',`<p class="form-help">将清除本原型的偏好、收藏和新建草稿，恢复示例首页。</p><div class="form-actions">${button('取消','close-modal','outline')}${button('重置本地数据','confirm-reset','primary')}</div>`);break;
 case 'confirm-reset':state={...defaults,bookmarks:[],drafts:[]};persist();eventQuery='';filter='recommended';statusFilter='all';savedOnly=false;closeModal();if(route().page!=='discover')setRoute('discover');else render();notify('已重置本原型的本地数据。');break;
 }}
document.addEventListener('click',event=>{const target=event.target.closest('button,a');if(!target)return;if(target.dataset.ai){reply(target.dataset.ai);return}if(target.dataset.filter){filter=target.dataset.filter;render();return}if(target.dataset.action){handleAction(target.dataset.action,target);return}if(target.hasAttribute('data-chat-navigate'))closeAssistant()});
document.addEventListener('submit',event=>{const form=event.target;if(!['hero-form','assistant-form','event-search','preference-form','filter-form','signup-form'].includes(form.id))return;event.preventDefault();const data=new FormData(form);switch(form.id){
 case 'hero-form':reply(data.get('prompt')||'这个周末，保定有哪些适合我的比赛？');form.reset();break;
 case 'assistant-form':reply(document.getElementById('assistant-input').value);form.reset();break;
 case 'event-search':eventQuery=String(data.get('query')||'').slice(0,100);render();break;
 case 'preference-form':state.city=['保定','全部'].includes(data.get('city'))?data.get('city'):'保定';state.level=['入门','日常爱好者','有赛事经验'].includes(data.get('level'))?data.get('level'):'入门';persist();closeModal();render();notify('运动偏好已保存在当前浏览器。');break;
 case 'filter-form':state.city=data.get('city');statusFilter=data.get('status');savedOnly=data.get('saved')==='on';persist();closeModal();render();break;
 case 'signup-form':{const e=findEvent(form.dataset.event),p=e?.projects.find(p=>p.id===data.get('project'));if(!e||!p||data.get('read')!=='on')return;const duplicate=state.drafts.some(d=>d.event===e.id&&d.project===p.id);if(duplicate){document.getElementById('signup-error').textContent='这个项目已经有一份本地草稿，请到「我的参赛」查看。';return}if(state.drafts.length>=20){document.getElementById('signup-error').textContent='本地草稿已达演示上限，请先删除不需要的草稿。';return}state.drafts.push({id:crypto.randomUUID(),event:e.id,project:p.id});persist();closeModal();appendMessage(`<strong>草稿已保存在当前浏览器。</strong><p>${e.name} · ${p.name}，成员确认 1/${p.members}。${p.members===2?'下一步需要伙伴本人确认。':'下一步需正式填写本人资料并校验资格。'}没有正式报名、占名额或付款。</p><a class="button outline" href="#participation" data-chat-navigate>查看我的草稿</a>`);notify('已保存本地草稿，尚未正式报名。');if(route().page==='participation')render();break}
 }});
document.addEventListener('change',event=>{if(event.target.matches('#signup-form select')){const form=event.target.form,e=findEvent(form.dataset.event),p=e.projects.find(p=>p.id===event.target.value);document.getElementById('signup-description').textContent=p.members===1?'单人项目，正式提交前须填写本人档案并核验资格。':'双人项目，需要伙伴本人填写并确认。'}});
document.getElementById('ai-launcher').addEventListener('click',()=>assistant.hidden?openAssistant():closeAssistant());document.getElementById('ai-close').addEventListener('click',closeAssistant);
document.getElementById('ai-expand').addEventListener('click',()=>{assistant.classList.toggle('expanded');const expanded=assistant.classList.contains('expanded');document.getElementById('ai-expand').setAttribute('aria-label',expanded?'还原聊天窗口':'放大聊天窗口');if(!expanded&&position){assistant.style.left=position.x+'px';assistant.style.top=position.y+'px'}clampAssistant()});
function clampAssistant(){if(assistant.hidden||assistant.classList.contains('expanded')||innerWidth<=760)return;const rect=assistant.getBoundingClientRect();position={x:Math.min(Math.max(12,rect.left),Math.max(12,innerWidth-rect.width-12)),y:Math.min(Math.max(86,rect.top),Math.max(86,innerHeight-rect.height-12))};assistant.style.left=position.x+'px';assistant.style.top=position.y+'px'}
const heading=assistant.querySelector('.assistant-heading');let drag=null;
heading.addEventListener('pointerdown',event=>{if(event.target.closest('button')||innerWidth<=760||assistant.classList.contains('expanded'))return;const rect=assistant.getBoundingClientRect();drag={x:event.clientX,y:event.clientY,left:rect.left,top:rect.top};heading.setPointerCapture(event.pointerId)});
heading.addEventListener('pointermove',event=>{if(!drag)return;assistant.style.left=drag.left+event.clientX-drag.x+'px';assistant.style.top=drag.top+event.clientY-drag.y+'px';clampAssistant()});heading.addEventListener('pointerup',()=>drag=null);heading.addEventListener('pointercancel',()=>drag=null);
window.addEventListener('resize',()=>{if(innerWidth<=760){assistant.style.left='';assistant.style.top='';position=null}else clampAssistant()});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.open&&!assistant.hidden)closeAssistant()});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal()}});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0)});render();
})();
